def _load_local_schedule_fallback(season_year: str = "2025-26") -> pd.DataFrame:
    for candidate in _local_schedule_candidates():
        if candidate.exists():
            df = pd.read_csv(candidate)
            if not df.empty:
                return df

    games_path = paths.data_raw / "games_nba_api.csv"
    if not games_path.exists():
        raise FileNotFoundError("games_nba_api.csv not found for NBA schedule fallback")

    games = pd.read_csv(games_path)
    required_columns = {"date", "home_team", "visitor_team", "game_id"}
    if games.empty or not required_columns.issubset(set(games.columns)):
        raise RuntimeError("Local NBA schedule fallback did not find usable games data")

    out = games.copy()
    season_start = int(str(season_year).split("-", 1)[0])
    season_end = season_start + 1
    out["date"] = pd.to_datetime(out["date"], errors="coerce")
    season_mask = out.get("season", pd.Series(dtype="object")).astype(str).eq(str(season_start))
    date_mask = out["date"].dt.year.isin([season_start, season_end])
    out = out[season_mask | date_mask].copy()
    if out.empty:
        raise RuntimeError(f"Local NBA schedule fallback did not find regular-season games for {season_year}")

    out["game_id"] = out["game_id"].astype(str)
    date_values = out["date"]
    out["season_year"] = season_year
    out["game_label"] = "Regular Season"
    out["game_subtype"] = None
    out["game_status"] = None
    out["game_status_text"] = None
    out["date_utc"] = None
    out["time_utc"] = None
    out["datetime_utc"] = None
    out["date_est"] = date_values.dt.date.astype(str)
    out["time_est"] = None
    out["datetime_est"] = None
    out["home_team_id"] = None
    out["home_tricode"] = None
    out["home_city"] = None
    out["home_name"] = None
    out["away_team_id"] = None
    out["away_tricode"] = None
    out["away_city"] = None
    out["away_name"] = None
    out["arena_name"] = None
    out["arena_city"] = None
    out["arena_state"] = None
    out["broadcasters_national"] = None
    out["date_utc"] = out["date_est"]
    out = out[[
        "game_id",
        "season_year",
        "game_label",
        "game_subtype",
        "game_status",
        "game_status_text",
        "date_utc",
        "time_utc",
        "datetime_utc",
        "date_est",
        "time_est",
        "datetime_est",
        "home_team_id",
        "home_tricode",
        "home_city",
        "home_name",
        "away_team_id",
        "away_tricode",
        "away_city",
        "away_name",
        "arena_name",
        "arena_city",
        "arena_state",
        "broadcasters_national",
    ]]
    return out


def _current_nba_season(today=None) -> str:
    """EDIT: the season in play on `today` ('2026-27' from July 2026), the one the schedule should carry."""
    import datetime as _dt

    d = today or _dt.date.today()
    start = d.year if d.month >= 7 else d.year - 1
    return f"{start}-{str(start + 1)[-2:]}"


_STATS_SCHEDULE_CACHE: dict[str, dict[str, Any]] = {}


def _stats_schedule_payload(season: str | None = None) -> dict[str, Any]:
    """EDIT: the CDN schedule payload rebuilt from stats.nba.com ScheduleLeagueV2, which carries the same game-level fields.

    cdn.nba.com/static/json/staticData/scheduleLeagueV2*.json answers 403 to this host (fleet and Windows, with or
    without browser headers, measured 2026-10-14), so the vendored command always took the local fallback and rewrote
    the previous season's file. One request per process (cached). Raises when the season has no games yet (e.g. before
    the schedule is published), which leaves the local fallback in charge exactly as before.
    """
    season = season or _current_nba_season()
    if season in _STATS_SCHEDULE_CACHE:
        return _STATS_SCHEDULE_CACHE[season]
    from nba_api.stats.endpoints.scheduleleaguev2 import ScheduleLeagueV2

    frame = ScheduleLeagueV2(league_id="00", season=season, timeout=60).get_data_frames()[0]
    if frame is None or frame.empty:
        raise RuntimeError(f"ScheduleLeagueV2 returned no games for {season}")

    def _v(row, col):
        val = row.get(col)
        if val is None or (isinstance(val, float) and pd.isna(val)) or (isinstance(val, str) and val == ""):
            return None
        return val

    by_date: dict[str, list[dict[str, Any]]] = {}
    for _, row in frame.iterrows():
        national = [{"broadcasterName": _v(row, f"nationalBroadcasters_{i}_broadcasterDisplay")} for i in range(5)
                    if _v(row, f"nationalBroadcasters_{i}_broadcasterDisplay")]
        game = {
            "gameId": _v(row, "gameId"), "gameLabel": _v(row, "gameLabel"), "gameSubtype": _v(row, "gameSubtype"),
            "gameStatus": _v(row, "gameStatus"), "gameStatusText": _v(row, "gameStatusText"),
            "gameDateTimeUTC": _v(row, "gameDateTimeUTC"), "gameDateUTC": _v(row, "gameDateUTC"), "gameTimeUTC": _v(row, "gameTimeUTC"),
            "gameDateTimeEst": _v(row, "gameDateTimeEst"), "gameDateEst": _v(row, "gameDateEst"), "gameTimeEst": _v(row, "gameTimeEst"),
            "homeTeam": {k: _v(row, f"homeTeam_{k}") for k in ("teamId", "teamTricode", "teamCity", "teamName")},
            "awayTeam": {k: _v(row, f"awayTeam_{k}") for k in ("teamId", "teamTricode", "teamCity", "teamName")},
            "arenaName": _v(row, "arenaName"), "arenaCity": _v(row, "arenaCity"), "arenaState": _v(row, "arenaState"),
            "broadcasters": {"national": national},
        }
        by_date.setdefault(str(_v(row, "gameDate") or ""), []).append(game)
    payload = {"leagueSchedule": {"seasonYear": str(frame["seasonYear"].iloc[0] or season),
                                  "gameDates": [{"gameDate": d, "games": g} for d, g in by_date.items()]}}
    _STATS_SCHEDULE_CACHE[season] = payload
    return payload


def fetch_schedule_2025_26() -> pd.DataFrame:
    """Fetch and normalize the 2025-26 NBA schedule from the public CDN feed.

    Returns a DataFrame with a stable schema suitable for frontend consumption:
    - game_id (str)
    - season_year (str like '2025-26')
    - game_label (e.g., 'Regular Season', 'Preseason', 'Playoffs')
    - game_subtype (e.g., 'PlayIn', 'InSeasonTournament' when applicable)
    - game_status (int) and game_status_text (str)
    - date_utc (YYYY-MM-DD) and time_utc (HH:MM) and datetime_utc (ISO8601)
    - date_est, time_est, datetime_est (local Eastern)
    - home_team_id, home_tricode, home_city, home_name
    - away_team_id, away_tricode, away_city, away_name
    - arena_name, arena_city, arena_state
    - broadcasters_national (pipe-delimited)
    """
    try:
        payload = _request_schedule_payload()
    except Exception:
        try:  # EDIT: the CDN answers 403 to this host; stats.nba.com serves the same feed
            payload = _stats_schedule_payload()
        except Exception:
            return _load_local_schedule_fallback()
    ls = payload.get("leagueSchedule", {})
    season_year = ls.get("seasonYear") or "2025-26"
    game_dates = ls.get("gameDates", []) or []

    if not game_dates:
        return _load_local_schedule_fallback(season_year)

    rows: list[dict[str, Any]] = []
    for gd in game_dates:
        games = gd.get("games", []) or []
        for g in games:
            # Basic fields with safe access
            game_id = str(g.get("gameId"))
            game_label = g.get("gameLabel")
            game_subtype = g.get("gameSubtype")
            game_status = g.get("gameStatus")
            game_status_text = g.get("gameStatusText")

            # Times
            dt_utc = g.get("gameDateTimeUTC") or g.get("gameTimeUTC")
            date_utc = g.get("gameDateUTC")
            time_utc = g.get("gameTimeUTC")
            dt_est = g.get("gameDateTimeEst") or g.get("gameTimeEst")
            date_est = g.get("gameDateEst")
            time_est = g.get("gameTimeEst")

            # Teams
            h = g.get("homeTeam", {}) or {}
            a = g.get("awayTeam", {}) or {}
            home_team_id = h.get("teamId")
            home_tricode = h.get("teamTricode")
            home_city = h.get("teamCity")
            home_name = h.get("teamName")
            away_team_id = a.get("teamId")
            away_tricode = a.get("teamTricode")
            away_city = a.get("teamCity")
            away_name = a.get("teamName")

            # Arena
            arena_name = g.get("arenaName")
            arena_city = g.get("arenaCity")
            arena_state = g.get("arenaState")

            # Broadcasters: national
            nat = []
            try:
                for b in (g.get("broadcasters", {}) or {}).get("national", []) or []:
                    name = b.get("broadcasterName")
                    if name:
                        nat.append(str(name))
            except Exception:
                pass
            broadcasters_national = " | ".join(nat) if nat else None

            rows.append({
                "game_id": game_id,
                "season_year": season_year,
                "game_label": game_label,
                "game_subtype": game_subtype,
                "game_status": game_status,
                "game_status_text": game_status_text,
                "date_utc": date_utc,
                "time_utc": time_utc,
                "datetime_utc": dt_utc,
                "date_est": date_est,
                "time_est": time_est,
                "datetime_est": dt_est,
                "home_team_id": home_team_id,
                "home_tricode": home_tricode,
                "home_city": home_city,
                "home_name": home_name,
                "away_team_id": away_team_id,
                "away_tricode": away_tricode,
                "away_city": away_city,
                "away_name": away_name,
                "arena_name": arena_name,
                "arena_city": arena_city,
                "arena_state": arena_state,
                "broadcasters_national": broadcasters_national,
            })

    df = pd.DataFrame(rows)
    # Normalize date columns to useful types for downstream if needed
    for col in ("datetime_utc", "datetime_est"):
        if col in df.columns:
            df[col] = pd.to_datetime(df[col], errors="coerce")
    for col in ("date_utc", "date_est"):
        if col in df.columns:
            df[col] = pd.to_datetime(df[col], errors="coerce").dt.date
    return df
